import argparse,collections,json,pathlib,re,subprocess
p=argparse.ArgumentParser();p.add_argument('root');p.add_argument('--bytes',type=int,default=16000);p.add_argument('--iterations',type=int,default=40);p.add_argument('--damping',type=float,default=.85);p.add_argument('--ast-grep',required=True);a=p.parse_args();root=pathlib.Path(a.root).resolve()
data=json.loads(subprocess.check_output([a.ast_grep,'outline','-l','rust','--items','structure','--json=compact',str(root)]))
files={};defs=collections.defaultdict(set);items={}
for row in data:
 path=pathlib.Path(row['path']);name=str(path.relative_to(root));files[name]=path.read_text();items[name]=row.get('items',[])
 def visit(xs):
  for x in xs:
   n=x.get('name','')
   if re.fullmatch(r'[A-Za-z_][A-Za-z_0-9]*',n):defs[n].add(name)
   visit(x.get('members',[]))
 visit(items[name])
graph={f:collections.Counter() for f in files}
for f,text in files.items():
 for symbol,count in collections.Counter(re.findall(r'\b[A-Za-z_][A-Za-z_0-9]*\b',text)).items():
  for target in defs.get(symbol,[]):
   if f!=target:graph[f][target]+=count/len(defs[symbol])
n=len(files);rank={f:1/n for f in files}
for _ in range(a.iterations):
 dangling=sum(rank[f] for f,edges in graph.items() if not edges);new={f:(1-a.damping)/n+a.damping*dangling/n for f in files}
 for f,edges in graph.items():
  total=sum(edges.values())
  for target,weight in edges.items():new[target]+=a.damping*rank[f]*weight/total
 rank=new
out='Ranked Rust map: lexical symbol-reference file graph, PageRank; edges are candidates, not resolved calls.\n'
for f in sorted(files,key=lambda f:(-rank[f],f)):
 lines=files[f].splitlines();block=f'\n{f} [rank {rank[f]:.6f}]\n'
 def render(xs,depth=0):
  result=''
